-- شغّلي بعد documents-schema.sql. يحتفظ بكل البيانات القديمة.
CREATE TABLE IF NOT EXISTS public.trainee_document_templates (
 template_id TEXT PRIMARY KEY,
 batch_name TEXT NOT NULL,
 document_kind TEXT NOT NULL CHECK(document_kind IN ('certificate','letter')),
 document_type TEXT NOT NULL,
 label TEXT NOT NULL,
 image_path TEXT NOT NULL,
 orientation TEXT NOT NULL DEFAULT 'landscape',
 name_settings JSONB NOT NULL DEFAULT '{"x":50,"y":47,"size":32,"color":"#1F4E46","width":74}'::jsonb,
 enabled BOOLEAN NOT NULL DEFAULT TRUE,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_document_templates_batch ON public.trainee_document_templates(batch_name);
ALTER TABLE public.trainee_document_templates ENABLE ROW LEVEL SECURITY;
-- لا تُمنح صلاحيات anon. الاستعلامات تتم من الخادم المصادق عليه.

